//! ⚡️ Layout artifact — OpText/OpBinary codecs for `LayoutMutation`. Mutation apply/inverse (via
//! `protocol::Mutation`/`protocol::SemanticMutation`, generated by `#[derive(dsl_derive::Mutations)]`
//! on the dispatch enum in `../../../🧬️schema/🧬️mutations/🦀️.rs`) is NOT this file's concern; this file only wires the
//! operation-log line/binary encodings.
//!
//! Every `LayoutMutation` variant wraps a plain local payload struct now (no foreign generic — the
//! pre-migration collection-op-flattening `LayoutMutationDsl`/`FramePatchDsl`/`ColorPatch`
//! mirrors this file (and `../../💾️binary/🧬️mutations/🦀️.rs`) used to carry, needed only to route around
//! the orphan rule for that op type's foreign generic and `FramePatch.fill`/`.stroke`'s
//! doubly-optional `Option<Option<[f32;4]>>` fields, are gone with it). `serde_json`'s compact
//! (single-line, declaration-order) encoding satisfies `OpText`/`OpBinary`'s laws directly:
//! `print_op` never contains `\n`, `parse_op(op.print_op()) == op`, and encoding is deterministic.

pub use crate::mutations::LayoutMutation;

//#region 📖️SemioGrammar
/// 📖️ Normative handcrafted text grammar for this facet (`dialect grammar`).
pub const COMPONENT_GRAMMAR_SEMIO: &str = include_str!("📖️.grammar.semio");
pub const COMPONENT_GRAMMAR_PATH: &str = concat!(module_path!(), "::📖️.grammar.semio");
//#endregion 📖️SemioGrammar

//#region 🔖️OpText
impl protocol::OpText for LayoutMutation {
    fn parse_op(line: &str) -> Result<Self, semio_framework_diagnostic::TextError> {
        semio_framework_pack_json::from_json_str(line, semio_framework_pack_json::JsonMemberPolicy::Reject).map_err(|e| semio_framework_diagnostic::TextError::new(semio_framework_value::ValueRefusalKind::InvalidValue, format!("invalid layout mutation line: {e}"), semio_framework_diagnostic::TextSpan::at(1, 1)))
    }
    fn print_op(&self) -> String {
        semio_framework_pack_json::to_json_string(self)
    }
}
//#endregion 🔖️OpText

